operations.body:
query ExploreCelestialBodies($search: String, $limit: Int = 10, $offset: Int = 0) {
  celestialBodies(search: $search, limit: $limit, offset: $offset) {
    pagination {
      count
      next
      previous
    }
    results {
      id
      name
      diameter
      mass
      gravity
      lengthOfDay
      atmosphere
      type {
        id
        name
      }
      image {
        imageUrl
        thumbnailUrl
      }
      description
      wikiUrl
    }
  }
}

query GetAstronautDetails($astronautId: Int!) {
  astronaut(id: $astronautId) {
    id
    name
    status {
      name
    }
    inSpace
    age
    dateOfBirth
    dateOfDeath
    firstFlight
    lastFlight
    timeInSpace
    evaTime
    agency {
      id
      name
      abbrev
      country {
        name
        nationalityName
      }
    }
    nationality {
      name
      nationalityName
      alpha2Code
    }
    image {
      imageUrl
      thumbnailUrl
    }
    bio
    wiki
    socialMediaLinks {
      url
      socialMediaSite
    }
  }
}

query GetAstronautsCurrentlyInSpace {
  astronauts(inSpace: true, search: "") {
    results {
      id
      name
      timeInSpace
      lastFlight
      agency {
        name
        abbrev
        country {
          name
        }
      }
      nationality {
        name
        nationalityName
      }
      image {
        thumbnailUrl
      }
    }
  }
}

query ListUpcomingLaunches {
  upcomingLaunches(limit: 10, ordering: "net") {
    pagination {
      count
    }
    results {
      id
      name
      net
      weatherConcerns
      rocket {
        id
        configuration {
          fullName
        }
      }
      mission {
        name
        description
      }
      webcastLive
      launchServiceProvider {
        name
      }
    }
  }
}
